namespace sv_696ba357c754453d9e6e2f440193299e.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// The circuit (and this service) survives enhanced navigation between pages.
/// </summary>
public sealed class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    /// <summary>
    /// Fired whenever theme or accent color changes.
    /// All subscribers (interactive components) re-render in response.
    /// </summary>
    public event Action? OnThemeChanged;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnThemeChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnThemeChanged?.Invoke();
    }

    public void ApplyPreferences(Theme theme, string accentColor)
    {
        var changed = CurrentTheme != theme || AccentColor != accentColor;
        CurrentTheme = theme;
        AccentColor = accentColor;
        if (changed) OnThemeChanged?.Invoke();
    }
}

@*
    Interactive island embedded in the static MainLayout.
    Because it has @rendermode, it runs in the circuit and can
    react to ThemeService.OnThemeChanged in real time.
*@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @ThemeIcon @ThemeService.CurrentTheme
</span>

@code {
    private string ThemeIcon => ThemeService.CurrentTheme switch
    {
        Theme.Light  => "☀️",
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "❓"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }
}

@*
    Reusable toggle — drop it on any interactive page or in the sidebar.
    Cycles through Light → Dark → System.
*@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary theme-toggle"
        style="border-color: @ThemeService.AccentColor; color: @ThemeService.AccentColor;"
        @onclick="CycleTheme"
        title="Toggle theme">
    @ThemeIcon @ThemeService.CurrentTheme
</button>

@code {
    private string ThemeIcon => ThemeService.CurrentTheme switch
    {
        Theme.Light  => "☀️",
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "❓"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        var next = ThemeService.CurrentTheme switch
        {
            Theme.Light  => Theme.Dark,
            Theme.Dark   => Theme.System,
            Theme.System => Theme.Light,
            _            => Theme.Light
        };
        ThemeService.SetTheme(next);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px; border-color: @ThemeService.AccentColor;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <select class="form-select" @bind="selectedTheme">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <option value="@t">@t</option>
            }
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Accent Color</label>
        <div class="d-flex align-items-center gap-2">
            <input type="color" class="form-control form-control-color"
                   @bind="selectedAccent" title="Choose accent color" />
            <code>@selectedAccent</code>
        </div>
    </div>

